-- Authorized correction: supersede only the nine old-verifier baseline
-- judgments. Keep their complete original rows in append-only audit history.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='60s';
CREATE TEMP TABLE arena618_schema_acl ON COMMIT DROP AS
 SELECT nspacl,has_schema_privilege('lab_arena_owner','public','CREATE') AS had_create
 FROM pg_namespace WHERE nspname='public';
GRANT CREATE ON SCHEMA public TO lab_arena_owner;

-- This exception applies only to the exact owner-created receipt in the same
-- transaction. No accepted payload, source execution or cache entry changes.
DO $terminal618$
DECLARE target OID:='public.lab_arena_runs_terminal_v1()'::regprocedure;
 d TEXT; metadata JSONB; addition TEXT:=$addition618$
  IF TG_OP='UPDATE' AND OLD.round_id='arena-2026-11-03'
    AND OLD.kind='score' AND OLD.status='accepted' AND OLD.terminal_cause='accepted'
    AND OLD.submission_id='baseline-2026-11-03' AND OLD.stage=1
    AND OLD.icp_position IN (0,1,2,3,4,5,6,7,9)
    AND OLD.scoring_generation_floor=0
    AND NEW.status='failed' AND NEW.terminal_cause='stage_closed'
    AND (to_jsonb(NEW)-ARRAY['status','terminal_cause','terminal_doc','updated_at'])=
        (to_jsonb(OLD)-ARRAY['status','terminal_cause','terminal_doc','updated_at'])
    AND NEW.terminal_doc=jsonb_build_object('operation','nov03_baseline_rejudge618_v1',
      'reason','superseded_old_verifier_judgment','request_id','nov03-baseline-rejudge618-v1')
    AND EXISTS(SELECT 1 FROM public.lab_arena_scoring_supersessions h
      WHERE h.round_id=OLD.round_id AND h.request_id='nov03-baseline-rejudge618-v1'
        AND h.transaction_id=txid_current() AND h.backend_pid=pg_backend_pid()
        AND h.recovery_doc->>'operation'='nov03_baseline_rejudge618_v1'
        AND h.recovery_doc->'superseded_judgments'->OLD.run_id=to_jsonb(OLD)) THEN
    NEW.updated_at:=clock_timestamp(); RETURN NEW;
  END IF;
$addition618$;
BEGIN
 SELECT pg_get_functiondef(p.oid),to_jsonb(p)-'prosrc' INTO d,metadata FROM pg_proc p WHERE p.oid=target;
 IF (SELECT pg_get_userbyid(proowner) FROM pg_proc WHERE oid=target)<>'lab_arena_owner'
  OR (SELECT proacl::TEXT FROM pg_proc WHERE oid=target) IS DISTINCT FROM '{lab_arena_owner=X/lab_arena_owner}' THEN
  RAISE EXCEPTION 'Nov03 rejudge terminal security differs'; END IF;
 IF encode(extensions.digest(d,'sha256'),'hex')='a59bf87b8823352c01c4ee4714e4475a857e0c6eda3092e447760ad3afcbd21e' THEN RETURN; END IF;
 IF encode(extensions.digest(d,'sha256'),'hex')<>'98edd53fc1f3756ff1829abce68f0f3ffae0911151778d4208d084160284c868'
  OR length(d)-length(replace(d,E'BEGIN\n',''))<>length(E'BEGIN\n') THEN
  RAISE EXCEPTION 'Nov03 rejudge terminal preimage differs'; END IF;
 EXECUTE replace(d,E'BEGIN\n',E'BEGIN\n'||addition);
 IF (SELECT to_jsonb(p)-'prosrc' FROM pg_proc p WHERE p.oid=target) IS DISTINCT FROM metadata
  OR encode(extensions.digest(pg_get_functiondef(target),'sha256'),'hex')<>'a59bf87b8823352c01c4ee4714e4475a857e0c6eda3092e447760ad3afcbd21e' THEN
  RAISE EXCEPTION 'Nov03 rejudge terminal readback differs'; END IF;
END;
$terminal618$;

-- A new root may follow a deliberately superseded accepted judgment. Ordinary
-- retry limits still count all previous attempts; no counter is reset.
DO $continuation618$
DECLARE target OID:='public.lab_arena__judge_continuation_v1(public.lab_arena_rounds,public.lab_arena_runs)'::regprocedure;
 d TEXT; metadata JSONB; anchor TEXT:='  -- The operator-created first attempt of this grading revision is a root;';
 addition TEXT:=$addition618$
  IF p_round.round_id='arena-2026-11-03' AND p_round.scoring_generation_floor=0
    AND p_run.submission_id='baseline-2026-11-03' AND p_run.stage=1
    AND p_run.icp_position IN (0,1,2,3,4,5,6,7,9)
    AND EXISTS(SELECT 1 FROM public.lab_arena_scoring_supersessions h,
      jsonb_array_elements(h.recovery_doc->'work_items') item
      WHERE h.round_id=p_round.round_id AND h.request_id='nov03-baseline-rejudge618-v1'
        AND h.recovery_doc->>'operation'='nov03_baseline_rejudge618_v1'
        AND h.new_round_doc->'configuration_doc'=p_round.configuration_doc
        AND item->>'new_run_id'=p_run.run_id
        AND (item->>'new_attempt')::INTEGER=p_run.attempt
        AND item->>'scored_run_id'=p_run.scored_run_id
        AND item->'company_judgment_refs'=p_run.company_judgment_refs
        AND EXISTS(SELECT 1 FROM public.lab_arena_runs original
          WHERE original.run_id=item->>'old_run_id' AND original.status='failed'
            AND original.terminal_cause='stage_closed'
            AND original.terminal_doc->>'operation'='nov03_baseline_rejudge618_v1'
            AND (to_jsonb(original)-ARRAY['status','terminal_cause','terminal_doc','updated_at'])=
              ((h.recovery_doc->'superseded_judgments'->original.run_id)-
                ARRAY['status','terminal_cause','terminal_doc','updated_at']))
    ) THEN RETURN TRUE; END IF;
$addition618$;
BEGIN
 SELECT pg_get_functiondef(p.oid),to_jsonb(p)-'prosrc' INTO d,metadata FROM pg_proc p WHERE p.oid=target;
 IF (SELECT pg_get_userbyid(proowner) FROM pg_proc WHERE oid=target)<>'lab_arena_owner'
  OR (SELECT proacl::TEXT FROM pg_proc WHERE oid=target) IS DISTINCT FROM '{lab_arena_owner=X/lab_arena_owner}' THEN
  RAISE EXCEPTION 'Nov03 rejudge continuation security differs'; END IF;
 IF encode(extensions.digest(d,'sha256'),'hex')='05818529181013b76affbe6253814cce6f6cbc2d4bdd0377f5ce57ef89191606' THEN RETURN; END IF;
 IF encode(extensions.digest(d,'sha256'),'hex')<>'ac7f91629dc1a1c7c30cb9b3fcb8eaf8a14132f533758144bea6dbc4257113e4'
  OR length(d)-length(replace(d,anchor,''))<>length(anchor) THEN
  RAISE EXCEPTION 'Nov03 rejudge continuation anchor differs'; END IF;
 EXECUTE replace(d,anchor,addition||anchor);
 IF (SELECT to_jsonb(p)-'prosrc' FROM pg_proc p WHERE p.oid=target) IS DISTINCT FROM metadata
  OR encode(extensions.digest(pg_get_functiondef(target),'sha256'),'hex')<>'05818529181013b76affbe6253814cce6f6cbc2d4bdd0377f5ce57ef89191606' THEN
  RAISE EXCEPTION 'Nov03 rejudge continuation readback differs'; END IF;
END;
$continuation618$;

DO $rejudge618$
