t-1.amazonaws.com/leadpoet/sourcing-model@sha256:3576adedad0e858b8a68b6760e61d0a060512ade572bc17f323f27a6e37f541b"}},{"cache_key":"sha256:3bcc98049f987365998000afe496be737aae4a430fca34a604cd76bf6a0a3eb9","company_index":4,"company_input_hash":"sha256:7bd7f026542895fa3691cd77e2ea667bbb6902fbc89fde047a55004cd3440235","schema_version":"leadpoet.lab_arena.company_judgment_ref.v1","scope_doc":{"cache_key":"sha256:3bcc98049f987365998000afe496be737aae4a430fca34a604cd76bf6a0a3eb9","company_input_hash":"sha256:7bd7f026542895fa3691cd77e2ea667bbb6902fbc89fde047a55004cd3440235","company_judgment_policy":"company_judgment_v1","evaluation_date":"2026-11-03","integrity_policy":"arena_integrity_v1","netuid":71,"network_name":"finney","round_id":"arena-2026-11-03","schema_version":"leadpoet.lab_arena.company_judgment_scope.v1","scorer_image_digest":"sha256:3576adedad0e858b8a68b6760e61d0a060512ade572bc17f323f27a6e37f541b","scorer_image_reference":"493765492819.dkr.ecr.us-east-1.amazonaws.com/leadpoet/sourcing-model@sha256:3576adedad0e858b8a68b6760e61d0a060512ade572bc17f323f27a6e37f541b"}}],"icp_position":9,"old_run_id":"arena-2026-11-03:baseline-2026-11-03:1:9:score:1","output_ref":"arena/arena-2026-11-03/outputs/arena-2026-11-03:baseline-2026-11-03:1:9:1.json","scored_run_id":"arena-2026-11-03:baseline-2026-11-03:1:9:1","submission_id":"baseline-2026-11-03"}]}$manifest618$::JSONB;
 r public.lab_arena_rounds; n public.lab_arena_rounds; c public.lab_arena_restart_claim_control;
 h public.lab_arena_scoring_supersessions; source public.lab_arena_runs; old_judge public.lab_arena_runs;
 item JSONB; work JSONB:='[]'; originals JSONB:='{}'; projections JSONB:='{}';
 revision BIGINT; request_hash TEXT; actual_hashes JSONB; before_ledger JSONB; next_attempt INTEGER;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('lab-arena-claim-control',0));
 SELECT * INTO STRICT c FROM public.lab_arena_restart_claim_control WHERE singleton FOR UPDATE;
 SELECT * INTO STRICT r FROM public.lab_arena_rounds WHERE round_id=rid FOR UPDATE;
 request_hash:='sha256:'||encode(extensions.digest(manifest::TEXT,'sha256'),'hex');
 SELECT * INTO h FROM public.lab_arena_scoring_supersessions WHERE round_id=rid AND request_id=request;
 IF FOUND THEN
  IF h.request_hash IS DISTINCT FROM request_hash
   OR h.recovery_doc->>'operation' IS DISTINCT FROM 'nov03_baseline_rejudge618_v1'
   OR h.new_round_doc->'configuration_doc' IS DISTINCT FROM r.configuration_doc THEN
   RAISE EXCEPTION 'Nov03 rejudge replay differs'; END IF;
  RETURN;
 END IF;
 IF current_setting('session_replication_role')<>'origin'
  OR c.operator_paused OR c.guard_generation IS DISTINCT FROM 759
  OR coalesce(c.guard_commitment,'')<>'' OR coalesce(c.owner_commitment,'')<>''
  OR c.guard_expires_at IS NOT NULL OR coalesce(c.candidate_commit,'')<>''
  OR coalesce(c.restart_scope,'')<>'' OR coalesce(c.restart_phase,'')<>''
  OR coalesce(c.captured_leases,'[]')<>'[]'::JSONB
  OR r.status<>'published' OR r.status_generation<>10 OR r.stage_generation<>7
  OR r.scoring_generation_floor<>0 OR r.published_at IS NULL OR r.publication_doc IS NULL
  OR r.reward_activated_at IS NULL OR r.reward_basis_doc IS NULL
  OR encode(extensions.digest(to_jsonb(r)::TEXT,'sha256'),'hex') IS DISTINCT FROM manifest->>'round_sha256'
  OR clock_timestamp()>='2026-11-03T23:45:00Z'::TIMESTAMPTZ
  OR jsonb_typeof(manifest->'work_items') IS DISTINCT FROM 'array'
  OR jsonb_array_length(manifest->'work_items')<>9
  OR EXISTS(SELECT 1 FROM public.lab_arena_runs WHERE round_id=rid AND status IN('pending','leased','submitted')) THEN
  RAISE EXCEPTION 'Nov03 rejudge exact round, guard, clock or drain differs'; END IF;
 SELECT jsonb_object_agg(a.run_id,encode(extensions.digest(to_jsonb(a)::TEXT,'sha256'),'hex')) INTO actual_hashes
 FROM public.lab_arena_runs a WHERE a.round_id=rid;
 IF actual_hashes IS DISTINCT FROM manifest->'run_hashes' THEN
  RAISE EXCEPTION 'Nov03 rejudge full run history differs'; END IF;
 SELECT jsonb_object_agg(a.run_id,encode(extensions.digest(to_jsonb(a)::TEXT,'sha256'),'hex')) INTO actual_hashes
 FROM public.lab_arena_runs a WHERE a.round_id=rid AND a.status='accepted';
 IF actual_hashes IS DISTINCT FROM manifest->'accepted_run_hashes'
  OR (SELECT count(*) FROM jsonb_object_keys(actual_hashes))<>210 THEN
  RAISE EXCEPTION 'Nov03 rejudge accepted history differs'; END IF;
 SELECT jsonb_build_object('count',count(*),'max',max(entry_id)) INTO before_ledger
 FROM public.lab_arena_ledger WHERE round_id=rid;
 n:=r; n.status:='scored'; n.status_generation:=r.status_generation+1;
 n.publication_doc:=NULL; n.published_at:=NULL; n.king_outcome:=NULL; n.king_hotkey:=NULL;
 n.configuration_doc:=jsonb_set(jsonb_set(r.configuration_doc,
  '{schedule,final_scoring_close}','"2026-11-03T23:45:00Z"'),
  '{schedule,publication_deadline}','"2026-11-03T23:59:00Z"');
 FOR item IN SELECT value FROM jsonb_array_elements(manifest->'work_items') LOOP
  SELECT * INTO STRICT source FROM public.lab_arena_runs WHERE run_id=item->>'scored_run_id' FOR UPDATE;
  SELECT * INTO STRICT old_judge FROM public.lab_arena_runs WHERE run_id=item->>'old_run_id' FOR UPDATE;
  IF source.round_id<>rid OR source.submission_id<>'baseline-2026-11-03' OR source.stage<>1
   OR source.icp_position NOT IN(0,1,2,3,4,5,6,7,9) OR source.kind<>'execute'
   OR source.status<>'accepted' OR source.terminal_cause<>'accepted' OR source.output_ref IS NULL
   OR source.output_ref IS DISTINCT FROM item->>'output_ref'
   OR source.submission_id IS DISTINCT FROM item->>'submission_id'
   OR source.icp_position IS DISTINCT FROM (item->>'icp_position')::INTEGER
   OR old_judge.round_id<>rid OR old_judge.kind<>'score' OR old_judge.status<>'accepted'
   OR old_judge.terminal_cause<>'accepted' OR old_judge.scoring_generation_floor<>0
   OR old_judge.scored_run_id<>source.run_id
   OR (old_judge.submission_id,old_judge.miner_hotkey,old_judge.stage,old_judge.icp_position)
      IS DISTINCT FROM (source.submission_id,source.miner_hotkey,source.stage,source.icp_position)
   OR NOT EXISTS(SELECT 1 FROM public.lab_arena_scoring_supersessions prior
     WHERE prior.round_id=rid AND prior.request_id='nov03-forward-only-verifier604-v1'
       AND prior.recovery_doc->'preserved_judgments'->old_judge.run_id->>'judge_sha256'=
         encode(extensions.digest(to_jsonb(old_judge)::TEXT,'sha256'),'hex'))
   OR NOT public.lab_arena__company_judgment_refs_v1(n,item->'company_judgment_refs')
   OR NOT public.lab_arena__judge_calls_clear_v1(old_judge.assignment_id)
   OR EXISTS(SELECT 1 FROM public.lab_arena_runs later WHERE later.assignment_id=old_judge.assignment_id
     AND later.attempt>old_judge.attempt) THEN
   RAISE EXCEPTION 'Nov03 rejudge exact source or prior authority differs'; END IF;
  next_attempt:=old_judge.attempt+1;
  originals:=originals||jsonb_build_object(old_judge.run_id,to_jsonb(old_judge));
  projections:=projections||jsonb_build_object(source.run_id,jsonb_build_object(
    'per_icp_score',source.per_icp_score,'qualification_doc',source.qualification_doc));
  work:=work||jsonb_build_array(item||jsonb_build_object('new_attempt',next_attempt,
    'new_run_id',old_judge.assignment_id||':'||next_attempt::TEXT,
    'source_immutable_sha256',encode(extensions.digest((to_jsonb(source)-
      ARRAY['per_icp_score','qualification_doc','updated_at'])::TEXT,'sha256'),'hex')));
 END LOOP;
 IF (SELECT count(DISTINCT x->>'scored_run_id') FROM jsonb_array_elements(work)x)<>9
  OR (SELECT count(DISTINCT x->>'old_run_id') FROM jsonb_array_elements(work)x)<>9 THEN
  RAISE EXCEPTION 'Nov03 rejudge duplicate work'; END IF;
 SELECT greatest(1,coalesce(max(generation_floor),0)+1) INTO revision
 FROM public.lab_arena_scoring_supersessions WHERE round_id=rid;
 INSERT INTO public.lab_arena_scoring_supersessions(round_id,generation_floor,request_id,request_hash,
  actor_ref,transaction_id,backend_pid,old_round_doc,new_round_doc,old_score_projections,recovery_doc)
 VALUES(rid,revision,request,request_hash,'nov03-baseline-rejudge618',txid_current(),pg_backend_pid(),
  to_jsonb(r)-'updated_at',to_jsonb(n)-'updated_at',projections,jsonb_build_object(
    'operation','nov03_baseline_rejudge618_v1','scoring_generation_floor',0,
    'superseded_judgments',originals,'work_items',work,'accepted_run_hashes',actual_hashes,
    'original_updated_at',r.updated_at));
 UPDATE public.lab_arena_rounds SET status=n.status,status_generation=n.status_generation,
  configuration_doc=n.configuration_doc,publication_doc=NULL,published_at=NULL,
  king_outcome=NULL,king_hotkey=NULL WHERE round_id=rid;
 UPDATE public.lab_arena_runs SET status='failed',terminal_cause='stage_closed',
  terminal_doc=jsonb_build_object('operation','nov03_baseline_rejudge618_v1',
    'reason','superseded_old_verifier_judgment','request_id',request)
 WHERE run_id IN(SELECT x->>'old_run_id' FROM jsonb_array_elements(work)x);
 UPDATE public.lab_arena_runs SET per_icp_score=NULL,qualification_doc=NULL
 WHERE run_id IN(SELECT x->>'scored_run_id' FROM jsonb_array_elements(work)x);
 FOR item IN SELECT value FROM jsonb_array_elements(work) LOOP
  SELECT * INTO STRICT old_judge FROM public.lab_arena_runs WHERE run_id=item->>'old_run_id';
  INSERT INTO public.lab_arena_runs(run_id,assignment_id,round_id,submission_id,miner_hotkey,
   stage,icp_position,attempt,status,stage_generation,kind,scored_run_id,company_judgment_refs)
  VALUES(item->>'new_run_id',old_judge.assignment_id,rid,old_judge.submission_id,old_judge.miner_hotkey,
   1,old_judge.icp_position,(item->>'new_attempt')::INTEGER,'pending',r.stage_generation,
   'score',old_judge.scored_run_id,item->'company_judgment_refs');
  IF NOT (SELECT public.lab_arena__judge_continuation_v1(n,a) FROM public.lab_arena_runs a
    WHERE a.run_id=item->>'new_run_id') THEN
   RAISE EXCEPTION 'Nov03 rejudge new continuation invalid'; END IF;
 END LOOP;
 IF (SELECT jsonb_build_object('count',count(*),'max',max(entry_id))
   FROM public.lab_arena_ledger WHERE round_id=rid) IS DISTINCT FROM before_ledger
  OR (SELECT to_jsonb(control) FROM public.lab_arena_restart_claim_control control WHERE singleton)
    IS DISTINCT FROM to_jsonb(c)
  OR (SELECT count(*) FROM public.lab_arena_runs WHERE round_id=rid)<>
     (SELECT count(*)+9 FROM jsonb_object_keys(manifest->'run_hashes'))
  OR EXISTS(SELECT 1 FROM jsonb_each_text(manifest->'run_hashes') expected
    LEFT JOIN public.lab_arena_runs actual ON actual.run_id=expected.key
    WHERE actual.run_id IS NULL OR CASE
      WHEN originals ? expected.key THEN
        actual.status<>'failed' OR actual.terminal_cause<>'stage_closed'
        OR (to_jsonb(actual)-ARRAY['status','terminal_cause','terminal_doc','updated_at'])<>
          ((originals->expected.key)-ARRAY['status','terminal_cause','terminal_doc','updated_at'])
      WHEN EXISTS(SELECT 1 FROM jsonb_array_elements(work)x WHERE x->>'scored_run_id'=expected.key) THEN
        actual.per_icp_score IS NOT NULL OR actual.qualification_doc IS NOT NULL
        OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(work)x WHERE x->>'scored_run_id'=actual.run_id
          AND x->>'source_immutable_sha256'=encode(extensions.digest((to_jsonb(actual)-
            ARRAY['per_icp_score','qualification_doc','updated_at'])::TEXT,'sha256'),'hex'))
      ELSE expected.value IS DISTINCT FROM encode(extensions.digest(to_jsonb(actual)::TEXT,'sha256'),'hex') END) THEN
  RAISE EXCEPTION 'Nov03 rejudge preserved state differs'; END IF;
END;
$rejudge618$;

DO $restore618$
BEGIN
 IF NOT (SELECT had_create FROM pg_temp.arena618_schema_acl) THEN REVOKE CREATE ON SCHEMA public FROM lab_arena_owner; END IF;
 IF (SELECT nspacl FROM pg_namespace WHERE nspname='public') IS DISTINCT FROM
  (SELECT nspacl FROM pg_temp.arena618_schema_acl) THEN RAISE EXCEPTION 'Nov03 rejudge schema ACL differs'; END IF;
END;
$restore618$;
NOTIFY pgrst,'reload schema';
COMMIT;
